{
  "criteria": [
    {
      "criterion": "claridad",
      "score": 3,
      "finding": "El requisito expresa el objetivo general pero utiliza términos no cuantificados: 'rápido y sencilla' generan interpretaciones contradictorias sobre qué tan rápido o cuántos pasos se consideran sencillos. No hay definición de la experiencia de búsqueda esperada.",
      "recommendation": "Definir umbrales de tiempo o número de pasos para considerar la búsqueda exitosa."
    },
    {
      "criterion": "especificidad",
      "score": 3,
      "finding": "El requisito describe un comportamiento deseado pero no especifica la lógica de filtrado, ordenamiento o qué se entiende por 'resultados relevantes'. No define qué productos se muestran ni bajo qué condiciones.",
      "recommendation": "Especificar los filtros disponibles, criterios de relevancia y formato de la lista de resultados."
    },
    {
      "criterion": "atomicidad",
      "score": 5,
      "finding": "El texto combina dos intenciones: (1) permitir la búsqueda de productos y (2) mostrar resultados relevantes. No están claramente separados en sub-requisitos independientes, pero la unión es estrechamente relacionada en una misma funcionalidad de usuario.",
      "recommendation": "Considerar separar si la funcionalidad de búsqueda y el filtrado/resultados relevantes son comportamientos distintos que podrían evolucionar de forma independiente."
    },
    {
      "criterion": "completitud",
      "score": 3,
      "finding": "Falta información crítica para desarrollar y probar: no se define el actor que ejecuta la búsqueda, las condiciones de entrada (palabras clave, filtros), ni el resultado esperado. No hay descripción de la interfaz ni de los datos de catálogo involucrados.",
      "recommendation": "Añadir quién puede buscar, qué datos de entrada se aceptan y qué se entiende por resultados mostrados."
    },
    {
      "criterion": "consistencia",
      "score": 6,
      "finding": "No hay contradicción explícita con otros requisitos entregados. El texto es autosuficiente dentro de la funcionalidad de búsqueda, pero carece de alineación con reglas de catálogo o flujos de compra no definidos en este fragmento.",
      "recommendation": "Verificar con el stakeholder si existen requisitos de catálogo o de carra que conflicten con el comportamiento de búsqueda."
    },
    {
      "criterion": "factibilidad",
      "score": 6,
      "finding": "Desde una perspectiva técnica, permitir búsquedas de productos es factible. Sin embargo, la falta de especificidad sobre 'rápido' y 'relevantes' dificulta estimar el esfuerzo de ingeniería necesario para cumplir con expectativas no definidas.",
      "recommendation": "Definir métricas de rendimiento aceptables para la búsqueda antes de validar la factibilidad."
    },
    {
      "criterion": "verificabilidad",
      "score": 3,
      "finding": "No hay condiciones medibles que permitan comprobar objetivamente si el requisito se cumple. No se pueden probar tiempos, relevancia ni simplicidad sin definiciones previas. No se especifica qué se observa ni cómo se mide.",
      "recommendation": "Establecer criterios de aceptación cuantificables (p. ej., 'tiempo de respuesta menor a 2 s', 'al menos el 80 % de los resultados contienen la palabra clave')."
    },
    {
      "criterion": "trazabilidad",
      "score": 5,
      "finding": "El requisito no incluye un identificador único ni declara explícitamente la necesidad o el actor de origen que permita relacionarlo con diseño, código y pruebas. No hay mención a historias de usuario, épicos o etiquetas de trazabilidad.",
      "recommendation": "Asignar un identificador REQ-XXX y enunciar el origen del requisito (p. ej., 'Como cliente, quiero buscar productos...')."
    },
    {
      "criterion": "ausencia_ambiguedad",
      "score": 3,
      "finding": "Se detectan términos subjetivos/vagos: 'rápido', 'sencilla' y 'relevantes'. Estos términos no tienen significado medible y su interpretación varía según el stakeholder. No están marcados como [POR DEFINIR] en el texto.",
      "recommendation": "Sustituir los términos ambiguos por condiciones medibles o valores umbral acordados con el cliente."
    },
    {
      "criterion": "criterios_aceptacion",
      "score": 2,
      "finding": "El requisito no incluye criterios de aceptación explícitos ni condiciones medibles de las que derivarlos. No hay definición de cuándo la búsqueda está 'satisfecha' ni qué resultados se consideran relevantes.",
      "recommendation": "Añadir criterios de aceptación cuantificables que permitan validar el cumplimiento del requisito."
    }
  ],
  "ambiguous_terms": [
    {
      "term": "rápido",
      "reason": "no define un tiempo medible"
    },
    {
      "term": "sencilla",
      "reason": "no define el número de pasos o complejidad aceptable"
    },
    {
      "term": "relevantes",
      "reason": "no especifica el criterio de filtrado o ranking de resultados"
    }
  ],
  "is_compound": true,
  "missing_information": [
    "actor que ejecuta la búsqueda (cliente invitado vs. registrado)",
    "palabras clave o campos de entrada aceptados",
    "filtros disponibles (precio, talla, marca, categoría)",
    "lógica de ordenamiento o ranking de resultados",
    "umbral de tiempo para considerar la búsqueda 'rápida'",
    "definición de 'resultados mostrados' (cantidad, formato)"
  ],
  "clarification_questions": [
    "¿Qué entiende el stakeholder por 'rápido' en términos de tiempo de respuesta o número de pasos de usuario?",
    "¿Cómo se determina qué resultado se considera 'relevante' para el cliente? ¿Hay filtros o ranking implícitos?",
    "¿La funcionalidad de búsqueda aplica tanto a clientes invitados como a los registrados, o hay diferencias en el comportamiento?",
    "¿Se deben especificar filtros por defecto o el usuario debe ingresarlos manualmente?"
  ],
  "summary": "El requisito define una intención de usuario pero incumple los criterios esenciales de especificidad, verificabilidad y criterios de aceptación por el uso de términos vagos y falta de datos medibles. Es necesario definir umbrales de tiempo, criterios de relevancia y condiciones de entrada para pasar a un desarrollo guiado por pruebas."
}
